//! Malformed logs, absurd inputs and file-system safety.
//!
//! The C comparisons cover damaged logs where rateup's behaviour is
//! well defined; the fuzz loops only require "no panic, sane output".

mod common;

use std::path::Path;

use common::*;
use linkscope_rate::{InputError, Mode, Period, RateError, RateLog, SummaryOpts, UpdateOutcome};

const LAB_LOG: &str = "/home/claude/build/lab/if0.log";

/// A valid ~2500 line log generated by the Rust port itself.
fn sample_log() -> Vec<u8> {
    let mut log = RateLog::fresh(1_700_000_000);
    let mut t = 1_700_000_000;
    for i in 0..40u64 {
        t += 300 + (i as i64 % 3) * 7;
        let v = (i * i * 1_234_567).to_string();
        log.update(t, &v, &v, i64::MAX, Mode::Counter, false);
    }
    log.render_bytes()
}

/// A named set of `(file name, content)` pairs.
type Case<'a> = (&'a str, Vec<(&'a str, &'a [u8])>);

/// Writes `files` into fresh C and Rust dirs, runs one update in both and
/// compares the results (including a C exit failure).
fn compare_one(bin: &Path, name: &str, files: &[(&str, &[u8])], now: i64, mode: Mode) {
    let cdir = TempDir::new("cor-c");
    for (f, d) in files {
        std::fs::write(cdir.path().join(f), d).unwrap();
    }
    let u = Upd {
        now,
        input: "123456".into(),
        output: "654321".into(),
        abs_max: i64::MAX,
        mode,
        zero: false,
    };
    let imgs: Vec<Img> = Period::ALL
        .iter()
        .map(|&period| Img {
            period,
            opts: SummaryOpts::default(),
        })
        .collect();
    let (ok, printed) = run_c(bin, cdir.path(), "t", now, Some(&u), &[], &imgs);
    let get = |f: &str| files.iter().find(|(n, _)| *n == f).map(|(_, d)| *d);
    let r = RateLog::from_bytes(get("t.log"), get("t.old"), now);
    match r {
        Err(RateError::Corrupt { .. }) => assert!(!ok, "{name}: Rust failed but C succeeded"),
        Err(e) => panic!("{name}: {e}"),
        Ok(mut log) => {
            assert!(ok, "{name}: C failed but Rust loaded");
            let out = log.update(now, &u.input, &u.output, u.abs_max, mode, false);
            assert_eq!(out, UpdateOutcome::Updated, "{name}");
            let c = std::fs::read(cdir.path().join("t.log")).unwrap();
            assert!(
                log.render_bytes() == c,
                "{name}: {}",
                first_diff(&log.render_bytes(), &c)
            );
            for (k, im) in imgs.iter().enumerate() {
                assert_eq!(
                    summary_lines(&log.summarize(now, im.period, &im.opts)),
                    printed[k],
                    "{name} {:?}",
                    im.period
                );
            }
        }
    }
}

#[test]
fn damaged_logs_match_c() {
    let Some(bin) = rateup() else { return };
    let good = sample_log();
    let now = 1_700_000_000 + 40 * 310;
    let text = String::from_utf8(good.clone()).unwrap();
    let lines: Vec<&str> = text.lines().collect();
    let join = |v: &[&str]| v.join("\n") + "\n";

    let mut unsorted = lines.clone();
    unsorted.swap(10, 500);
    let unsorted = join(&unsorted);
    let mut garbage_mid = lines.clone();
    garbage_mid.insert(300, "this is not a number");
    garbage_mid.insert(310, "");
    garbage_mid.insert(320, "   \t ");
    garbage_mid.insert(330, "1699000000 12");
    garbage_mid.insert(340, "1699000000 12 x 4 5");
    let garbage_mid = join(&garbage_mid);
    let mut long_line = lines.clone();
    let filler = format!(
        "{} 1 2 3 4{}",
        lines[100].split(' ').next().unwrap(),
        " 9".repeat(200)
    );
    long_line[100] = &filler;
    let long_line = join(&long_line);
    let bad_first = format!("garbage\n{}", lines[1..].join("\n"));
    let two_fields = format!("{} 77\n{}\n", now - 300, lines[1..].join("\n"));
    let three_col = {
        let mut s = format!("{} 1000 2000\n", now - 300);
        let mut t = now - 300;
        for i in 0..700u64 {
            s += &format!("{t} {} {}\n", i * 100, i * 7);
            t -= 300;
        }
        s
    };
    let inmax_low = text.replacen(" 0 0 0 0\n", " 900 800 1 2\n", 30);
    let line_only = format!("{} 5 6\n", now - 200);
    let huge = format!(
        "{}{}",
        text,
        (0..3000)
            .map(|i| format!("{} 1 1 1 1\n", 1_000_000_000 - i * 300))
            .collect::<String>()
    );
    let long_last = format!(
        "{} {} {}\n{}",
        now - 300,
        "7".repeat(250),
        "8".repeat(10),
        lines[1..].join("\n")
    );
    let overflow = text.replacen(
        " 0 0 0 0\n",
        " 99999999999999999999999 -99999999999999999999 1 2\n",
        5,
    );
    let neg_time = text.replacen(" 0 0 0 0\n", " 0 0 0 0\n-5 1 1 1 1\n", 1);
    let crlf = text.replace('\n', "\r\n");

    let cases: Vec<Case<'_>> = vec![
        ("missing both", vec![]),
        ("empty log", vec![("t.log", b"")]),
        ("unsorted log, no old", vec![("t.log", unsorted.as_bytes())]),
        (
            "unsorted log, good old",
            vec![("t.log", unsorted.as_bytes()), ("t.old", &good)],
        ),
        (
            "unsorted log and old",
            vec![
                ("t.log", unsorted.as_bytes()),
                ("t.old", unsorted.as_bytes()),
            ],
        ),
        (
            "bad first line, good old",
            vec![("t.log", bad_first.as_bytes()), ("t.old", &good)],
        ),
        (
            "bad first line, no old",
            vec![("t.log", bad_first.as_bytes())],
        ),
        (
            "two fields in line 1",
            vec![("t.log", two_fields.as_bytes())],
        ),
        ("garbage lines", vec![("t.log", garbage_mid.as_bytes())]),
        ("long line", vec![("t.log", long_line.as_bytes())]),
        ("three columns", vec![("t.log", three_col.as_bytes())]),
        ("inmax below avg", vec![("t.log", inmax_low.as_bytes())]),
        ("line 1 only", vec![("t.log", line_only.as_bytes())]),
        (
            "more than MAX_HISTORY lines",
            vec![("t.log", huge.as_bytes())],
        ),
        ("250 char last value", vec![("t.log", long_last.as_bytes())]),
        ("overflowing numbers", vec![("t.log", overflow.as_bytes())]),
        ("negative time", vec![("t.log", neg_time.as_bytes())]),
        ("crlf line ends", vec![("t.log", crlf.as_bytes())]),
    ];
    let lab;
    if let Ok(l) = std::fs::read(LAB_LOG) {
        lab = l;
        let files: Vec<(&str, &[u8])> = vec![("t.log", b"x\n1 2 3 4 5\n"), ("t.old", &lab)];
        compare_one(
            &bin,
            "bad log, lab old (stale tail)",
            &files,
            1_760_006_500,
            Mode::Counter,
        );
    }
    for (name, files) in &cases {
        for mode in [Mode::Counter, Mode::Gauge] {
            compare_one(&bin, name, files, now, mode);
        }
    }
}

/// Random corruption of a valid log, compared with C. The first history
/// line is kept intact because a short first line reads uninitialised
/// stack memory in rateup.
#[test]
fn mutated_logs_match_c() {
    let Some(bin) = rateup() else { return };
    let good = sample_log();
    let now = 1_700_000_000 + 40 * 310 + 300;
    let first_two = good
        .iter()
        .enumerate()
        .filter(|(_, b)| **b == b'\n')
        .nth(1)
        .unwrap()
        .0
        + 1;
    let iters = env_num("MRTG_RATE_MUTATIONS", 150);
    for seed in 0..iters {
        let mut rng = Rng::new(seed + 1000);
        let mut d = good.clone();
        for _ in 0..1 + rng.below(6) {
            let pos = first_two + rng.below((d.len() - first_two) as u64) as usize;
            match rng.below(5) {
                0 => {
                    d.remove(pos);
                }
                1 => d.insert(pos, rng.pick(b"0123456789 \n-+x.")),
                2 => d[pos] = rng.pick(b"0123456789 \n-+x."),
                3 => {
                    let end = (pos + rng.below(200) as usize).min(d.len());
                    d.drain(pos..end);
                }
                _ => {
                    let chunk: Vec<u8> = d[pos..(pos + 40).min(d.len())].to_vec();
                    d.splice(pos..pos, chunk);
                }
            }
        }
        let with_old = rng.chance(50);
        let mut files: Vec<(&str, &[u8])> = vec![("t.log", &d)];
        if with_old {
            files.push(("t.old", &good));
        }
        compare_one(
            &bin,
            &format!("mutation seed {seed}"),
            &files,
            now,
            Mode::Counter,
        );
    }
}

#[test]
fn random_bytes_never_panic() {
    let good = sample_log();
    let opts = SummaryOpts {
        maxx: 60,
        bits: true,
        peak: true,
        dorelpercent: true,
        ..SummaryOpts::default()
    };
    for seed in 0..300u64 {
        let mut rng = Rng::new(seed);
        let data: Vec<u8> = match seed % 3 {
            0 => (0..rng.below(5000)).map(|_| rng.next_u64() as u8).collect(),
            1 => (0..rng.below(5000))
                .map(|_| rng.pick(b"0123456789 \n\t-+.\0ex"))
                .collect(),
            _ => {
                let mut d = good.clone();
                for _ in 0..20 {
                    let p = rng.below(d.len() as u64) as usize;
                    d[p] = rng.next_u64() as u8;
                }
                d
            }
        };
        let now = rng.pick(&[
            0i64,
            -1,
            1_700_020_000,
            i64::MAX,
            i64::MIN,
            i64::MAX / 2,
            i64::MIN / 2,
        ]);
        let Ok(mut log) = RateLog::from_bytes(Some(&data), Some(&data), now) else {
            continue;
        };
        let _ = log.render();
        for p in Period::ALL {
            let _ = log.summarize(now, p, &opts);
        }
        for mode in [
            Mode::Counter,
            Mode::Absolute,
            Mode::Gauge,
            Mode::PerHour,
            Mode::PerMinute,
        ] {
            let t = now.wrapping_add(rng.below(4000) as i64);
            let _ = log.update(
                t,
                "18446744073709551616000",
                "-1",
                rng.next_u64() as i64,
                mode,
                rng.chance(50),
            );
            let _ = log.render();
            let _ = log.summarize(t, Period::Year, &opts);
        }
    }
}

#[test]
fn absurd_inputs_are_rejected_or_handled() {
    let mut log = RateLog::fresh(1_700_000_000);
    let long = "1".repeat(200);
    assert_eq!(
        log.update(1_700_000_300, &long, "1", 10, Mode::Counter, false),
        UpdateOutcome::Rejected(InputError::TooLong)
    );
    assert_eq!(
        log.update(1_700_000_300, "", "1", 10, Mode::Counter, false),
        UpdateOutcome::Rejected(InputError::Empty)
    );
    assert_eq!(
        log.update(1_700_000_300, "1 2", "1", 10, Mode::Counter, false),
        UpdateOutcome::Rejected(InputError::BadChar)
    );
    assert_eq!(
        log.update(1_700_000_300, "1\x002", "1", 10, Mode::Counter, false),
        UpdateOutcome::Rejected(InputError::BadChar)
    );
    // Strange first update: no diff happens, so a digit-less value is fine
    // (rateup writes it), but the next update would diff it.
    assert_eq!(
        log.update(1_700_000_300, "abc", "5", 10, Mode::Counter, false),
        UpdateOutcome::Updated
    );
    assert_eq!(
        log.update(1_700_000_600, "7", "9", 10, Mode::Counter, false),
        UpdateOutcome::Rejected(InputError::NoDigits)
    );
    assert_eq!(log.last_raw(), ("abc", "5"));
    let ok198 = "9".repeat(198);
    assert_eq!(
        log.update(1_700_000_600, &ok198, "9", 10, Mode::Gauge, false),
        UpdateOutcome::Rejected(InputError::TooLongForDiff)
    );
    // A 197-digit gauge does not fit in i64: becomes the previous rate.
    let ok197 = "9".repeat(197);
    assert_eq!(
        log.update(1_700_000_600, &ok197, "9", i64::MAX, Mode::Gauge, false),
        UpdateOutcome::Updated
    );
    // Extreme timestamps must not panic.
    for t in [i64::MAX, i64::MAX - 1] {
        let mut l = RateLog::fresh(t);
        let _ = l.update(t, "1", "1", i64::MAX, Mode::Counter, true);
        let _ = l.render();
        let _ = l.summarize(t, Period::Day, &SummaryOpts::default());
    }
    let mut l = RateLog::fresh(i64::MIN);
    let _ = l.update(i64::MIN, "1", "1", i64::MAX, Mode::Counter, true);
    let _ = l.update(i64::MAX, "1", "1", i64::MAX, Mode::Counter, true);
    let _ = l.summarize(
        i64::MIN,
        Period::Year,
        &SummaryOpts {
            maxx: 10_000,
            ..SummaryOpts::default()
        },
    );
    assert!(RateLog::load(Path::new("/nonexistent"), &"x".repeat(121), 0).is_err());
}

#[cfg(unix)]
#[test]
fn save_is_atomic_and_never_follows_symlinks() {
    use std::os::unix::fs::{PermissionsExt, symlink};
    let dir = TempDir::new("save");
    let p = dir.path();
    let mut log = RateLog::load(p, "t", 1_700_000_000).unwrap();
    log.update(1_700_000_000, "1", "2", i64::MAX, Mode::Counter, false);
    log.save(p, "t").unwrap();
    let meta = std::fs::metadata(p.join("t.log")).unwrap();
    assert_eq!(meta.permissions().mode() & 0o777 & !0o022, 0o644 & !0o022);
    assert!(!p.join("t.old").exists() || std::fs::read(p.join("t.old")).is_ok());
    log.update(1_700_000_300, "301", "602", i64::MAX, Mode::Counter, false);
    log.save(p, "t").unwrap();
    assert_eq!(std::fs::read(p.join("t.log")).unwrap(), log.render_bytes());
    assert!(p.join("t.old").exists());

    // Temp names are unpredictable: a link or file planted at the old
    // pid-based name is neither followed nor able to block the save.
    let victim = p.join("victim");
    std::fs::write(&victim, b"precious").unwrap();
    let planted = p.join(format!("t.tmp_{}", std::process::id()));
    symlink(&victim, &planted).unwrap();
    log.save(p, "t").unwrap();
    assert_eq!(std::fs::read(&victim).unwrap(), b"precious");
    std::fs::remove_file(&planted).unwrap();

    // If t.log is a symlink, the link itself is renamed, its target untouched.
    std::fs::remove_file(p.join("t.log")).unwrap();
    symlink(&victim, p.join("t.log")).unwrap();
    log.save(p, "t").unwrap();
    assert_eq!(std::fs::read(&victim).unwrap(), b"precious");
    assert!(
        std::fs::symlink_metadata(p.join("t.old"))
            .unwrap()
            .file_type()
            .is_symlink()
    );
    assert!(
        std::fs::symlink_metadata(p.join("t.log"))
            .unwrap()
            .file_type()
            .is_file()
    );
}

#[cfg(unix)]
#[test]
fn fifo_or_symlinked_log_is_not_read() {
    use linkscope_rate::RateLog;
    let dir = std::env::temp_dir().join(format!("linkscope-rate-fifo-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let fifo = dir.join("f.log");
    let _ = std::fs::remove_file(&fifo);
    let ok = std::process::Command::new("mkfifo")
        .arg(&fifo)
        .status()
        .map(|s| s.success())
        .unwrap_or(false);
    if ok {
        // Must return promptly (fresh log) instead of blocking on the FIFO.
        let t = std::time::Instant::now();
        let l = RateLog::load(&dir, "f", 1_700_000_000).unwrap();
        assert!(t.elapsed() < std::time::Duration::from_secs(2));
        assert!(l.history_len() > 0);
    }
    let real = dir.join("real.log");
    std::fs::write(&real, b"1700000000 5 5\n1700000000 1 1 1 1\n").unwrap();
    let _ = std::fs::remove_file(dir.join("s.log"));
    std::os::unix::fs::symlink(&real, dir.join("s.log")).unwrap();
    let l = RateLog::load(&dir, "s", 1_700_000_100).unwrap();
    assert_ne!(
        l.last_raw(),
        ("5", "5"),
        "symlinked log must not be followed"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

/// 4 MB of blank lines (each repeats the line before) became about 170 MB of history: reading
/// stops well past any log rateup writes (2026-10-21).
#[test]
fn a_log_of_blank_lines_is_read_with_bounded_history() {
    let mut data = b"1700000000 100 200\n1700000000 1 1 1 1\n".to_vec();
    data.resize(data.len() + 4_000_000, b'\n');
    let log = RateLog::from_bytes(Some(&data), None, 1_700_000_300).unwrap();
    // 16 times MAX_HISTORY (600 + 600 + 600 + 732 + 10).
    assert!(log.history_len() <= 16 * 2542, "{}", log.history_len());
    // A normal log is read whole, as before.
    let good = sample_log();
    let normal = RateLog::from_bytes(Some(&good), None, 1_700_020_000).unwrap();
    assert_eq!(normal.render_bytes(), good);
}
